package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimResponse;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Service;

/** Closes a period, fixing its due-total as it is now: the dues as shown now of the claims whose due-by is in it that counted
 *  at the end of its last day (see {@link Person#countsAtEnd}), each with its late charge, and each person's share of it (a person's unbound OPEN claims dated within one of their holds count in none; a claim whose due is n/a adds nothing).
 *  Used by a close by hand and by the auto close when the sheet's today is changed (see {@link #closeDue}). */
@Service
public class PeriodCloser {

    private final Periods periods;
    private final People people;
    private final Claims claims;
    private final Rates rates;
    private final Settings settings;
    private final Sheets sheets;
    private final Audit audit;

    public PeriodCloser(Periods periods, People people, Claims claims, Rates rates, Settings settings, Sheets sheets,
            Audit audit) {
        this.periods = periods;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.settings = settings;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** Close the open (or soft-closed) period, auditing PERIOD_CLOSED (with auto=yes when closed by the auto close). */
    public void close(String sheetId, PeriodResponse period, String user, boolean auto) {
        close(sheetId, period, user, auto, false);
    }

    /** Soft-close the open period: its figures are fixed as by a close, but its claims stay open to change.
     *  Audits PERIOD_SOFT_CLOSED. */
    public void softClose(String sheetId, PeriodResponse period, String user) {
        close(sheetId, period, user, false, true);
    }

    private void close(String sheetId, PeriodResponse period, String user, boolean auto, boolean soft) {
        LocalDate from = LocalDate.parse(period.from());
        LocalDate to = LocalDate.parse(period.to());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        LocalDate policyDate = settings.policyDate(sheetId);
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.list(sheetId);
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        for (Person person : people.list(sheetId)) {
            BigDecimal personTotal = BigDecimal.ZERO.setScale(2);
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !person.countsAtEnd(claim, to, today)
                        || claim.getPeriodDate().isBefore(from) || claim.getPeriodDate().isAfter(to)) {
                    continue;
                }
                RoundingMode rounding = Rounding.of(claim, policyDate, on -> settings.roundingMode(sheetId, on));
                BigDecimal fixed = ClaimResponse.fixedDue(claim);
                BigDecimal figure = fixed != null || claim.isBound() ? fixed
                        : Rates.due(claim.getAmount(), rates.find(claim, person.gradeOn(claim.getDate())), rounding);
                if (figure != null) {
                    personTotal = personTotal.add(LateCharge.due(claim, figure, settings.floor(sheetId, claim.getDate()),
                            on -> settings.latePct(sheetId, on), today, rounding,
                            settings.grace(sheetId, person.gradeOn(claim.getDate()), claim.getDate())));
                }
            }
            personTotals.put(person.getId(), personTotal);
            total = total.add(personTotal);
        }
        periods.close(sheetId, period.name(), total, personTotals, soft);
        audit.recordOnCommit((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheetId + " by=" + user
                + " period=" + period.name() + " total=" + total.toPlainString() + (auto ? " auto=yes" : ""));
    }

    /** The auto close, once the sheet's today is set: with grace days set, every open period whose to-date plus
     *  them is before the sheet's today is closed, in order of their to-dates; a soft-closed period is left as it is. */
    public void closeDue(String sheetId, String user) {
        Integer grace = settings.graceDays(sheetId);
        if (grace == null) {
            return;
        }
        LocalDate today = sheets.today(sheetId);
        List<PeriodResponse> due = periods.list(sheetId).stream()
                .filter(p -> !p.closed() && !p.softClosed() && LocalDate.parse(p.to()).plusDays(grace).isBefore(today))
                .sorted(java.util.Comparator.comparing(PeriodResponse::to))
                .toList();
        for (PeriodResponse period : due) {
            PeriodResponse locked = periods.lock(sheetId, period.name());
            if (locked != null && !locked.closed() && !locked.softClosed()) {
                close(sheetId, locked, user, true);
            }
        }
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowCallbackHandler;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The period store: named, non-overlapping date ranges (both ends inclusive), kept per sheet. */
@Repository
public class Periods {

    private static final RowMapper<PeriodResponse> ROW = (rs, i) -> {
        BigDecimal total = rs.getBigDecimal("closed_total");
        return new PeriodResponse(rs.getString("name"), rs.getDate("from_date").toLocalDate().toString(),
                rs.getDate("to_date").toLocalDate().toString(), rs.getBoolean("closed"),
                total == null ? "" : total.setScale(2).toPlainString(), new LinkedHashMap<>(),
                rs.getBoolean("soft_closed"), rs.getObject("claim_cap") == null ? "" : String.valueOf(rs.getInt("claim_cap")));
    };

    private final JdbcTemplate jdbc;

    public Periods(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's periods, by from-date. */
    public List<PeriodResponse> list(String sheetId) {
        List<PeriodResponse> periods = jdbc.query("SELECT * FROM period WHERE sheet_id = ? ORDER BY from_date", ROW, sheetId);
        Map<String, PeriodResponse> byName = new HashMap<>();
        periods.forEach(p -> byName.put(p.name(), p));
        jdbc.query("SELECT period_name, person_id, total FROM period_person_total WHERE sheet_id = ? ORDER BY person_id",
                (RowCallbackHandler) rs -> {
                    PeriodResponse period = byName.get(rs.getString("period_name"));
                    if (period != null) {
                        period.closedPersonTotals().put(String.valueOf(rs.getLong("person_id")),
                                rs.getBigDecimal("total").setScale(2).toPlainString());
                    }
                }, sheetId);
        return periods;
    }

    /** The named period, its row locked until the transaction ends; null when none. */
    public PeriodResponse lock(String sheetId, String name) {
        List<PeriodResponse> found = jdbc.query("SELECT * FROM period WHERE sheet_id = ? AND name = ? FOR UPDATE",
                ROW, sheetId, name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Close (or soft-close) the named period, fixing its due-total and each person's due-total for it. */
    public void close(String sheetId, String name, BigDecimal total, Map<Long, BigDecimal> personTotals, boolean soft) {
        jdbc.update("UPDATE period SET closed = ?, soft_closed = ?, closed_total = ? WHERE sheet_id = ? AND name = ?",
                !soft, soft, total, sheetId, name);
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?", sheetId, name);
        personTotals.forEach((personId, personTotal) -> jdbc.update(
                "INSERT INTO period_person_total (sheet_id, period_name, person_id, total) VALUES (?, ?, ?, ?)",
                sheetId, name, personId, personTotal));
        history(sheetId, name, !soft, soft, total, personTotals);
    }

    /** Records a close, soft-close or reopen of the period in its history, dated the sheet's today. */
    private void history(String sheetId, String name, boolean closed, boolean soft, BigDecimal total,
            Map<Long, BigDecimal> personTotals) {
        StringBuilder totals = new StringBuilder();
        personTotals.forEach((personId, personTotal) -> totals.append(totals.isEmpty() ? "" : ";").append(personId)
                .append('=').append(personTotal.setScale(2).toPlainString()));
        jdbc.update("INSERT INTO period_history (sheet_id, name, set_on, closed, soft_closed, closed_total, person_totals)"
                + " VALUES (?, ?, (SELECT today FROM sheet WHERE id = ?), ?, ?, ?, ?)", sheetId, name, sheetId, closed, soft,
                total, totals.toString());
    }

    /** Reopen the named period, dropping its fixed due-total. */
    public void reopen(String sheetId, String name) {
        jdbc.update("UPDATE period SET closed = FALSE, soft_closed = FALSE, closed_total = NULL WHERE sheet_id = ? AND name = ?",
                sheetId, name);
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?", sheetId, name);
        history(sheetId, name, false, false, null, Map.of());
    }

    /** Whether a date falls inside a closed period of the sheet. */
    public boolean isClosed(String sheetId, LocalDate date) {
        Integer closed = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet_id = ? AND closed AND from_date <= ? AND to_date >= ?",
                Integer.class, sheetId, Date.valueOf(date), Date.valueOf(date));
        return closed != null && closed > 0;
    }

    /** Whether a date falls inside a soft-closed period of the sheet. */
    public boolean isSoftClosed(String sheetId, LocalDate date) {
        Integer soft = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet_id = ? AND soft_closed AND from_date <= ? AND to_date >= ?",
                Integer.class, sheetId, Date.valueOf(date), Date.valueOf(date));
        return soft != null && soft > 0;
    }

    /** The name of the sheet's period whose dates contain the date; null when none does. */
    public String nameOn(String sheetId, LocalDate date) {
        List<String> found = jdbc.query("SELECT name FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?",
                (rs, i) -> rs.getString(1), sheetId, Date.valueOf(date), Date.valueOf(date));
        return found.isEmpty() ? null : found.get(0);
    }

    /** The capped period whose dates contain the date, its row locked until the transaction ends (so two
     *  claims opened at once cannot both pass its cap); null when no period contains it or that one has no cap. */
    public PeriodResponse cappedOn(String sheetId, LocalDate date) {
        List<PeriodResponse> found = jdbc.query("SELECT * FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?"
                + " AND claim_cap IS NOT NULL FOR UPDATE", ROW, sheetId, Date.valueOf(date), Date.valueOf(date));
        return found.isEmpty() ? null : found.get(0);
    }

    /** Add a period, refusing a name already on the sheet or dates overlapping another period. */
    public void add(String sheetId, ValidPeriod period) throws InvalidPeriodException {
        // Lock the sheet's row so two periods added at once cannot both pass the overlap check.
        jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", (rs, i) -> rs.getString(1), sheetId);
        Integer named = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND name = ?",
                Integer.class, sheetId, period.name());
        if (named != null && named > 0) {
            throw new InvalidPeriodException("A period named " + period.name() + " is already on the sheet");
        }
        Integer overlapping = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?",
                Integer.class, sheetId, Date.valueOf(period.to()), Date.valueOf(period.from()));
        if (overlapping != null && overlapping > 0) {
            throw new InvalidPeriodException("The period's dates overlap another period");
        }
        try {
            jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date, added_on, claim_cap) VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?), ?)",
                    sheetId, period.name(), Date.valueOf(period.from()), Date.valueOf(period.to()), sheetId, period.cap());
        } catch (DuplicateKeyException raced) {
            throw new InvalidPeriodException("A period named " + period.name() + " is already on the sheet");
        }
    }

    /** Add a period unless its name is already on the sheet or its dates overlap another period:
     *  whether it was added. */
    public boolean addIfFree(String sheetId, ValidPeriod period) {
        try {
            add(sheetId, period);
            return true;
        } catch (InvalidPeriodException taken) {
            return false;
        }
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { readPath, useAsOf } from '../asof/useAsOf';

/** A period: a name unique on the sheet, from and to dates (YYYY-MM-DD, both inclusive), whether it
 *  is closed, the due-total fixed when it was closed ("" while open), and each person's due-total for
 *  it fixed then, by person id (empty while open; a person added later has none). A soft-closed period
 *  has its figures fixed the same way, but its claims stay open to change. Its cap is the most OPEN or PENDING
 *  claims a person may have in it ("" for none): opening one more is refused. */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string;
  closedPersonTotals: Record<string, string>;
  softClosed: boolean;
  cap: string;
};

export const periodsKey = (sheet: string, asOf = '') => ['sheet', sheet, 'periods', asOf] as const;

/** The sheet's periods, by from-date. */
export function usePeriods(sheet: string): Period[] {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: periodsKey(sheet, asOf),
    queryFn: () => getJson<Period[]>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/periods`, asOf)),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** The fiscal year a date falls in, named FY<yyyy> by the calendar year its first day falls in, for a
 *  fiscal year starting in the month (1 to 12). */
export function fiscalYearOf(date: string, startMonth: number): string {
  const year = Number(date.slice(0, 4));
  const month = Number(date.slice(5, 7));
  return `FY${month >= startMonth ? year : year - 1}`;
}

/** The period whose dates contain a date; periods never overlap, so there is at most one. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}
